def compute_order_amount(on_hand_inventory, pipeline_orders):
    # New stationary policy with fractional base-stock targeting
    base_stock = 600  # OPT_PARAM: {'initial': 600, 'min': 100, 'max': 1000, 'type': 'int'}
    max_order = 450   # OPT_PARAM: {'initial': 450, 'min': 0, 'max': 600, 'type': 'int'}
    gamma = 0.85      # OPT_PARAM: {'initial': 0.85, 'min': 0.5, 'max': 1.0, 'type': 'float'}
    pipeline_sum = sum(pipeline_orders)
    target = base_stock - on_hand_inventory - pipeline_sum
    order_amount = int(max(0, min(max_order, gamma * target)))
    return order_amount
